package com.hs.jxc.md;
import com.hs.jxc.fin.api.LedgerApi;import com.hs.jxc.common.db.BookGate;import com.hs.jxc.fin.service.BookResolver;import com.hs.jxc.common.api.*;import com.hs.jxc.common.context.RequestContext;import com.hs.jxc.common.audit.AuditWriter;import com.hs.jxc.common.db.DbRows;import com.hs.jxc.common.idempotency.IdempotencyExecutor;import com.hs.jxc.sys.api.Access;import com.hs.jxc.sys.service.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional
public class SupplierService {
 private final JdbcTemplate jdbc;private final AuthorizationService auth;private final AuditWriter audit;private final IdempotencyExecutor idem;private final FieldPolicyService fields;private final BankAccountCipher cipher;private final LedgerApi ledger;private final BookGate gates;private final BookResolver books;
 public SupplierService(JdbcTemplate j,AuthorizationService a,AuditWriter w,IdempotencyExecutor i,FieldPolicyService f,BankAccountCipher cipher,LedgerApi ledger,BookGate gates,BookResolver books){jdbc=j;auth=a;audit=w;idem=i;fields=f;this.cipher=cipher;this.ledger=ledger;this.gates=gates;this.books=books;}
 private String table(String kind){return switch(kind){case "suppliers"->"md_supplier";case "logistics-providers"->"md_logistics_provider";case "expense-items"->"md_expense_item";default->throw ApiException.notFound();};}
 private boolean expense(String kind){return kind.equals("expense-items");}private String edit(String kind){return expense(kind)?"md:expense-item:edit":"md:partner:edit";}
 public Object list(RequestContext c,String kind,Map<String,String> query){
  Access a=auth.authorize(c);a.require(expense(kind)?"md:expense-item:edit":"md:partner:view","pur:order:create","lgs:shipment:create","lgs:fee:create","ap:bill:view",expense(kind)?"cst:expense:create":"md:partner:view");
  String status=listFilter(query,"status",Set.of("ENABLED","DISABLED"),"状态筛选不合法");
  String type=kind.equals("partners")?listFilter(query,"partnerType",Set.of("SUPPLIER","LOGISTICS","BOTH"),"往来单位类型筛选不合法"):null;
  List<String> kinds=!kind.equals("partners")?List.of(kind):"SUPPLIER".equals(type)?List.of("suppliers"):"LOGISTICS".equals(type)?List.of("logistics-providers"):List.of("suppliers","logistics-providers");
  Map<Long,Map<String,Object>> selected=new LinkedHashMap<>();
  for(String source:kinds){
   var args=status==null?new Object[]{a.requireCountry()}:new Object[]{a.requireCountry(),status};
   for(var value:jdbc.queryForList("SELECT * FROM "+table(source)+" WHERE country_id=?"+(status==null?"":" AND status=?")+" ORDER BY id DESC",args)){
    var row=out(a,source,DbRows.camel(value));
    if("BOTH".equals(type)&&!"BOTH".equals(row.get("partnerType")))continue;
    selected.putIfAbsent(((Number)row.get("id")).longValue(),row);
   }
  }
  var rows=new ArrayList<>(selected.values());
  return Map.of("records",rows,"total",rows.size(),"page",1,"size",rows.size());
 }
 /** 清空筛选控件表示不筛选；非法值必须明确报错。 */
 private static String listFilter(Map<String,String> query,String key,Set<String> allowed,String message){
  String value=query.get(key);if(value==null||value.isBlank())return null;
  if(!allowed.contains(value))throw Inputs.bad(message);return value;
 }
 public Map<String,Object> get(RequestContext c,String kind,long id){Access a=auth.authorize(c);a.require(expense(kind)?"md:expense-item:edit":"md:partner:view","pur:order:create","lgs:shipment:create",expense(kind)?"cst:expense:create":"md:partner:view");if(kind.equals("partners"))kind=partnerKind(a,id);return out(a,kind,row(a,kind,id,false));}
 public Map<String,Object> save(RequestContext c,String kind,Long id,Map<String,Object>b,String key){Access a=auth.authorize(c);a.require(edit(kind));fields.requireWrite(a,b,"COST");if(expense(kind))return saveExpense(c,a,id,b,key);String k=kind;if(k.equals("partners"))k=id==null?(Inputs.text(b,"partnerType","SUPPLIER").equals("LOGISTICS")?"logistics-providers":"suppliers"):partnerKind(a,id);String target=k;if(id==null)return idem.execute(c,"POST","/api/v1/md/"+kind,key,b,null,()->{var r=write(c,a,target,null,b);if("BOTH".equals(b.get("partnerType"))){long rid=((Number)r.get("id")).longValue();jdbc.update("INSERT INTO md_logistics_provider(id,country_id,code,name,settle_currency,located_country,payment_terms,contact,phone,address,created_by) SELECT id,country_id,code,name,settle_currency,located_country,payment_terms,contact,phone,address,created_by FROM md_supplier WHERE country_id=? AND id=?",a.requireCountry(),rid);syncBoth(a,rid);}return r;},r->row(a,target,((Number)r.get("id")).longValue(),false));var saved=write(c,a,target,id,b);if(kind.equals("partners")&&jdbc.queryForObject("SELECT count(*) FROM md_supplier s JOIN md_logistics_provider l ON l.country_id=s.country_id AND l.id=s.id WHERE s.country_id=? AND s.id=?",Integer.class,a.requireCountry(),id)==1)syncBoth(a,id);return saved;}
 private Map<String,Object> saveExpense(RequestContext c,Access a,Long id,Map<String,Object>b,String key){
  var old=id==null?null:row(a,"expense-items",id,false);Long oldAccount=old==null||old.get("accountId")==null?null:Inputs.id(old.get("accountId"));Long account=b.containsKey("accountId")?(b.get("accountId")==null?null:Inputs.id(b.get("accountId"))):oldAccount;Long selected=b.get("bookId")==null?null:Inputs.id(b.get("bookId"));Long book=null;if(oldAccount!=null&&account==null&&selected==null)throw Inputs.bad("清空会计科目时请明确原账套");
  if(oldAccount!=null){var reference=ledger.validateAccountReference(a,selected,oldAccount);book=((Number)reference.get("bookId")).longValue();}
  if(account!=null){var reference=ledger.validateAccountReference(a,book==null?selected:book,account);book=((Number)reference.get("bookId")).longValue();}else if(book==null&&selected!=null){book=books.resolve(a,selected,null);gates.lock(a.requireCountry(),book,true);}
  final Long selectedBook=book;return idem.execute(c,id==null?"POST":"PUT","/api/v1/md/expense-items"+(id==null?"":"/"+id),key,b,selectedBook,()->{
   var before=id==null?null:row(a,"expense-items",id,true);if(before!=null&&Inputs.version(b)!=((Number)before.get("version")).longValue())throw Inputs.conflict();String code=Inputs.required(b,"code"),name=Inputs.required(b,"name"),treatment=Inputs.required(b,"costTreatment");if(!Set.of("CAPITALIZE","EXPENSE","PERIOD_EXPENSE","DIRECT_SELLING").contains(treatment))throw Inputs.bad("费用成本处理不合法");long result;
   if(id==null)result=jdbc.queryForObject("INSERT INTO md_expense_item(country_id,code,name,cost_treatment,fee_category,account_id,created_by) VALUES(?,?,?,?,?,?,?) RETURNING id",Long.class,a.requireCountry(),code,name,treatment,Inputs.text(b,"feeCategory",""),account,c.userId());else{if(jdbc.update("UPDATE md_expense_item SET code=?,name=?,cost_treatment=?,fee_category=?,account_id=?,version=version+1 WHERE country_id=? AND id=? AND version=?",code,name,treatment,Inputs.text(b,"feeCategory",""),account,a.requireCountry(),id,Inputs.version(b))!=1)throw Inputs.conflict();result=id;}
   var out=out(a,"expense-items",row(a,"expense-items",result,false));audit.append(c,"配置费用项目","expense-item",result,before==null?null:out(a,"expense-items",before),out);return out;
  },r->{var saved=row(a,"expense-items",((Number)r.get("id")).longValue(),false);if(saved.get("accountId")!=null)ledger.validateAccountReference(a,selectedBook,Inputs.id(saved.get("accountId")));});
 }
 private void syncBoth(Access a,long id){jdbc.update("UPDATE md_logistics_provider l SET (code,name,settle_currency,located_country,payment_terms,contact,phone,address,bank_name,account_name,account_no_masked,account_no_encrypted,status)=(SELECT code,name,settle_currency,located_country,payment_terms,contact,phone,address,bank_name,account_name,account_no_masked,account_no_encrypted,status FROM md_supplier s WHERE s.country_id=l.country_id AND s.id=l.id),version=version+1 WHERE l.country_id=? AND l.id=?",a.requireCountry(),id);}

 private Map<String,Object> write(RequestContext c,Access a,String kind,Long id,Map<String,Object>b){String tbl=table(kind),code=Inputs.required(b,"code"),name=Inputs.required(b,"name");String currency=Inputs.text(b,"settleCurrency","CNY");if(jdbc.queryForObject("SELECT count(*) FROM md_currency WHERE code=? AND status='ENABLED'",Integer.class,currency)!=1)throw Inputs.bad("结算币种未启用");String account=Inputs.text(b,"accountNo",null),masked=account==null?Inputs.text(b,"accountNoMasked",""):"****"+account.substring(Math.max(0,account.length()-4));if(id==null)id=jdbc.queryForObject("INSERT INTO "+tbl+"(country_id,code,name,settle_currency,located_country,payment_terms,contact,phone,address,bank_name,account_name,account_no_masked,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,a.requireCountry(),code,name,currency,Inputs.text(b,"locatedCountry","CN"),Inputs.text(b,"paymentTerms",""),Inputs.text(b,"contact",""),Inputs.text(b,"phone",""),Inputs.text(b,"address",""),Inputs.text(b,"bankName",""),Inputs.text(b,"accountName",""),masked,a.userId());else{var old=row(a,kind,id,true);if(jdbc.update("UPDATE "+tbl+" SET code=?,name=?,settle_currency=?,located_country=?,payment_terms=?,contact=?,phone=?,address=?,bank_name=?,account_name=?,account_no_masked=?,version=version+1 WHERE country_id=? AND id=? AND version=?",code,name,currency,Inputs.text(b,"locatedCountry",String.valueOf(old.get("locatedCountry"))),Inputs.text(b,"paymentTerms",String.valueOf(old.get("paymentTerms"))),Inputs.text(b,"contact",String.valueOf(old.get("contact"))),Inputs.text(b,"phone",String.valueOf(old.get("phone"))),Inputs.text(b,"address",String.valueOf(old.get("address"))),Inputs.text(b,"bankName",String.valueOf(old.get("bankName"))),Inputs.text(b,"accountName",String.valueOf(old.get("accountName"))),account==null?Inputs.text(b,"accountNoMasked",String.valueOf(old.get("accountNoMasked"))):masked,a.requireCountry(),id,Inputs.version(b))!=1)throw Inputs.conflict();}if(!expense(kind)&&b.get("accountNo") instanceof String raw&&!raw.isBlank())jdbc.update("UPDATE "+tbl+" SET account_no_encrypted=? WHERE country_id=? AND id=?",cipher.encrypt(raw),a.requireCountry(),id);var r=out(a,kind,row(a,kind,id,false));audit.append(c,"SAVE",kind,id,null,r);return r;}
 public Map<String,Object> toggle(RequestContext c,String kind,long id,boolean enabled){Access a=auth.authorize(c);a.require(edit(kind));if(kind.equals("partners"))kind=partnerKind(a,id);var old=row(a,kind,id,true);jdbc.update("UPDATE "+table(kind)+" SET status=?,version=version+1 WHERE country_id=? AND id=?",enabled?"ENABLED":"DISABLED",a.requireCountry(),id);var r=out(a,kind,row(a,kind,id,false));audit.append(c,"STATUS",kind,id,out(a,kind,old),r);return r;}
 public Object banks(RequestContext c,long id){Access a=auth.authorize(c);a.require("md:partner:bank-view");if(FieldPolicyService.rank(a.fieldGroups().get("BANK_INFO"))<1)throw ApiException.forbidden();var r=row(a,partnerKind(a,id),id,false);audit.append(c,"BANK_VIEW","PARTNER",id,null,null);return String.valueOf(r.get("bankName")).isBlank()?List.of():List.of(Map.of("bankName",r.get("bankName"),"accountName",r.get("accountName"),"accountNoMasked",r.get("accountNoMasked"),"currency",r.get("settleCurrency"),"isDefault",true));}
 private String partnerKind(Access a,long id){if(jdbc.queryForObject("SELECT count(*) FROM md_supplier WHERE country_id=? AND id=?",Integer.class,a.requireCountry(),id)>0)return "suppliers";if(jdbc.queryForObject("SELECT count(*) FROM md_logistics_provider WHERE country_id=? AND id=?",Integer.class,a.requireCountry(),id)>0)return "logistics-providers";throw ApiException.notFound();}
 private Map<String,Object> out(Access a,String kind,Map<String,Object>r){r=new LinkedHashMap<>(r);r.remove("accountNoEncrypted");if(expense(kind)&&r.get("accountId")!=null){var matches=jdbc.queryForList("SELECT book_id FROM fin_account WHERE country_id=? AND id=?",a.requireCountry(),r.get("accountId"));if(!matches.isEmpty()){long book=((Number)matches.getFirst().get("book_id")).longValue();if(a.canBook(book))r.put("bookId",book);else r.remove("accountId");}}if(!expense(kind)){boolean both=jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM md_supplier s JOIN md_logistics_provider l ON l.country_id=s.country_id AND l.id=s.id WHERE s.country_id=? AND s.id=?)",Boolean.class,a.requireCountry(),r.get("id"));r.put("partnerType",both?"BOTH":kind.equals("suppliers")?"SUPPLIER":"LOGISTICS");boolean visible=a.has("md:partner:bank-view")&&FieldPolicyService.rank(a.fieldGroups().get("BANK_INFO"))>0;if(!visible)for(String k:List.of("bankName","accountName","accountNoMasked"))r.remove(k);r.put("bankHidden",!visible);}return fields.mask(a,r,"COST");}
 private Map<String,Object> row(Access a,String kind,long id,boolean lock){var r=jdbc.queryForList("SELECT * FROM "+table(kind)+" WHERE country_id=? AND id=?"+(lock?" FOR UPDATE":""),a.requireCountry(),id);if(r.isEmpty())throw ApiException.notFound();return DbRows.camel(r.getFirst());}
}
